// Vectors generated by the TypeScript reference
// (typescript/test/interops/generate-service-identity-vectors.ts and
// generate-service-anchor-vectors.ts).

func readJSON(t *testing.T, name string, v interface{}) {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("..", "..", "test", "compatibility", "testdata", name))
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(data, v); err != nil {
		t.Fatal(err)
	}
}

type identityVectors struct {
	Canonical []struct {
		Input   string `json:"input"`
		Options struct {
			AllowDevelopmentHosts bool `json:"allowDevelopmentHosts"`
		} `json:"options"`
		Output string `json:"output"`
	} `json:"canonical"`
	Master string `json:"master"`
	Derive []struct {
		Service   string `json:"service"`
		Canonical string `json:"canonical"`
		Alg       string `json:"alg"`
		Type      int    `json:"type"`
		TypeName  string `json:"typeName"`
		Info      string `json:"info"`
		Entropy   string `json:"entropy"`
		DID       string `json:"did"`
		IDSha256  string `json:"idSha256"`
		ID        string `json:"id"`
	} `json:"derive"`
}

func roleOf(typeName string) (string, bool) {
	for _, r := range []string{"machine", "person", "organization"} {
		if typeName == r {
			return r, false
		}
		if typeName == r+"-pq" {
			return r, true
		}
	}
	return "", false
}

func TestCanonicalVectors(t *testing.T) {
	var v identityVectors
	readJSON(t, "service-identity-vectors.json", &v)
	if len(v.Canonical) == 0 {
		t.Fatal("no vectors")
	}
	for _, c := range v.Canonical {
		got, err := CanonicalServiceID(c.Input, c.Options.AllowDevelopmentHosts)
		if err != nil {
			got = "invalid"
		}
		if got != c.Output {
			t.Errorf("CanonicalServiceID(%q, %v) = %q, want %q", c.Input, c.Options.AllowDevelopmentHosts, got, c.Output)
		}
	}
}

func TestDeriveVectors(t *testing.T) {
	var v identityVectors
	readJSON(t, "service-identity-vectors.json", &v)
	master, _ := hex.DecodeString(v.Master)
	checked := 0
	for _, d := range v.Derive {
		role, pq := roleOf(d.TypeName)
		opts := Options{Alg: d.Alg, Role: role, PostQuantum: pq}
		canonical, err := CanonicalServiceID(d.Service, false)
		if err != nil || canonical != d.Canonical {
			t.Fatalf("canonical(%q) = %q, %v", d.Service, canonical, err)
		}
		if hex.EncodeToString(Info(d.Alg, role, pq, canonical)) != d.Info {
			t.Errorf("info mismatch for %s %s %s", d.Service, d.Alg, d.TypeName)
		}
		entropy, err := DeriveEntropy(master, d.Service, opts)
		if err != nil || hex.EncodeToString(entropy) != d.Entropy {
			t.Errorf("entropy mismatch for %s %s %s: %v", d.Service, d.Alg, d.TypeName, err)
		}
		id, err := Derive(master, d.Service, opts)
		if err != nil {
			t.Fatalf("Derive(%s, %s): %v", d.Service, d.Alg, err)
		}
		if id.DID() != d.DID {
			t.Errorf("did mismatch for %s %s: %s != %s", d.Service, d.Alg, id.DID(), d.DID)
		}
		sum := sha256.Sum256(id.ToBytes())
		if hex.EncodeToString(sum[:]) != d.IDSha256 {
			t.Errorf("id mismatch for %s %s %s", d.Service, d.Alg, d.TypeName)
		}
		if d.ID != "" && hex.EncodeToString(id.ToBytes()) != d.ID {
			t.Errorf("serialized id mismatch for %s", d.Service)
		}
		checked++
	}
	// every vector, hybrid (dilithium_ed25519) and post-quantum types included
	if checked != len(v.Derive) || checked < 16 {
		t.Fatalf("only %d of %d identities checked", checked, len(v.Derive))
	}
}

func TestDeriveRefusals(t *testing.T) {
	master := bytes.Repeat([]byte{1}, 32)
	if _, err := Derive(make([]byte, 32), "https://example.com", Options{}); err != ErrInvalidMasterSecret {
		t.Error("zero master accepted")
	}
	if _, err := Derive(master[:31], "https://example.com", Options{}); err != ErrInvalidMasterSecret {
		t.Error("short master accepted")
	}
	if _, err := Derive(master, "https://example.com/login", Options{}); err != ErrInvalidServiceID {
		t.Error("path accepted")
	}
	if _, err := Derive(master, "https://example.com", Options{Alg: "rsa"}); err == nil {
		t.Error("unknown alg accepted")
	}
	if _, err := Derive(master, "https://example.com", Options{Role: "admin"}); err == nil {
		t.Error("unknown role accepted")
	}
	if _, err := Derive(master, "https://example.com", Options{PostQuantum: true}); err == nil {
		t.Error("post-quantum ed25519 accepted")
	}
	a, _ := Derive(master, "https://service-a.test", Options{})
	b, _ := Derive(master, "https://service-b.test", Options{})
	if a.DID() == b.DID() {
		t.Error("two services share an identity")
	}
}

func TestAnchorVectors(t *testing.T) {
	var v struct {
		Valid []struct {
			ServiceID string `json:"serviceId"`
			DID       string `json:"did"`
			Anchor    string `json:"anchor"`
		} `json:"valid"`
		Invalid []struct {
			Name      string `json:"name"`
			ServiceID string `json:"serviceId"`
			Anchor    string `json:"anchor"`
		} `json:"invalid"`
	}
	readJSON(t, "service-anchor-vectors.json", &v)
	var master []byte
	{
		sum := sha256.Sum256([]byte("vaultysid/test/anchors/service"))
		master = sum[:]
	}
	for _, a := range v.Valid {
		raw, _ := hex.DecodeString(a.Anchor)
		id := VerifyAnchor(raw, a.ServiceID)
		if id == nil || id.DID() != a.DID {
			t.Errorf("valid anchor refused for %s", a.ServiceID)
		}
		// Ed25519 signatures are deterministic: Go must produce the same bytes.
		service, err := Derive(master, a.ServiceID, Options{Role: "organization"})
		if err != nil {
			t.Fatal(err)
		}
		mine, err := CreateAnchor(service, a.ServiceID)
		if err != nil || !bytes.Equal(mine, raw) {
			t.Errorf("Go anchor differs from TypeScript for %s", a.ServiceID)
		}
	}
	for _, a := range v.Invalid {
		raw, _ := hex.DecodeString(a.Anchor)
		if VerifyAnchor(raw, a.ServiceID) != nil {
			t.Errorf("invalid anchor accepted: %s", a.Name)
		}
	}
}

// Anchors of hybrid (dilithium_ed25519) service identities, made by TypeScript:
// Go verifies them, derives the same identity from the same master, and builds
// the same anchor up to the signature (hedged ML-DSA in Go, deterministic in
// the vectors), which then verifies too.
func TestHybridAnchorVectors(t *testing.T) {
	var v struct {
		Hybrid struct {
			Alg   string `json:"alg"`
			Role  string `json:"role"`
			Valid []struct {
				ServiceID       string `json:"serviceId"`
				PostQuantum     bool   `json:"postQuantum"`
				Type            int    `json:"type"`
				DID             string `json:"did"`
				IDSha256        string `json:"idSha256"`
				SignatureLength int    `json:"signatureLength"`
				Anchor          string `json:"anchor"`
			} `json:"valid"`
			Invalid []struct {
				Name      string `json:"name"`
				ServiceID string `json:"serviceId"`
				Anchor    string `json:"anchor"`
			} `json:"invalid"`
		} `json:"hybrid"`
	}
	readJSON(t, "service-anchor-vectors.json", &v)
	if v.Hybrid.Alg != "dilithium_ed25519" || len(v.Hybrid.Valid) != 2 || len(v.Hybrid.Invalid) < 4 {
		t.Fatalf("unexpected hybrid anchor vectors: %s, %d valid, %d invalid", v.Hybrid.Alg, len(v.Hybrid.Valid), len(v.Hybrid.Invalid))
	}
	sum := sha256.Sum256([]byte("vaultysid/test/anchors/service"))
	master := sum[:]
	for _, a := range v.Hybrid.Valid {
		raw, _ := hex.DecodeString(a.Anchor)
		id := VerifyAnchor(raw, a.ServiceID)
		if id == nil || id.DID() != a.DID {
			t.Fatalf("hybrid anchor refused for %s (post-quantum %v)", a.ServiceID, a.PostQuantum)
		}
		service, err := Derive(master, a.ServiceID, Options{Alg: v.Hybrid.Alg, Role: v.Hybrid.Role, PostQuantum: a.PostQuantum})
		if err != nil {
			t.Fatal(err)
		}
		idSum := sha256.Sum256(service.ToBytes())
		if service.DID() != a.DID || int(service.Type) != a.Type || hex.EncodeToString(idSum[:]) != a.IDSha256 {
			t.Fatalf("Go derives another hybrid identity: %s, want %s", service.DID(), a.DID)
		}
		mine, err := CreateAnchor(service, a.ServiceID)
		if err != nil {
			t.Fatal(err)
		}
		unsignedLength := len(raw) - a.SignatureLength
		if len(mine) != len(raw) || !bytes.Equal(mine[:unsignedLength], raw[:unsignedLength]) {
			t.Fatal("Go hybrid anchor differs from TypeScript before the signature")
		}
		if VerifyAnchor(mine, a.ServiceID) == nil {
			t.Fatal("Go hybrid anchor refused")
		}
	}
	for _, a := range v.Hybrid.Invalid {
		raw, _ := hex.DecodeString(a.Anchor)
		if VerifyAnchor(raw, a.ServiceID) != nil {
			t.Errorf("invalid hybrid anchor accepted: %s", a.Name)
		}
	}
}

func TestAnchorRoundTripDilithium(t *testing.T) {
	service, err := vaultysid.GenerateOrganizationAlg("dilithium")
	if err != nil {
		t.Fatal(err)
	}
	anchor, err := CreateAnchor(service, "https://service-a.test")
	if err != nil {
		t.Fatal(err)
	}
	if id := VerifyAnchor(anchor, "https://service-a.test"); id == nil || id.DID() != service.DID() {
		t.Error("dilithium anchor refused")
	}
	if VerifyAnchor(anchor, "https://service-b.test") != nil {
		t.Error("anchor accepted for another origin")
	}
	if u, _ := AnchorURL("https://Service-A.test/"); u != "https://service-a.test/.well-known/vaultysid-service" {
		t.Error(u)
	}
	if _, err := AnchorURL("app:test.service.c"); err == nil {
		t.Error("anchor URL for app: id")
	}
	if _, err := AnchorURL("contact:" + strings.Repeat("ab", 32)); err == nil {
		t.Error("anchor URL for contact: id")
	}
}

func TestContactID(t *testing.T) {
	hexValue := strings.Repeat("0123456789abcdef", 4)
	id := ContactPrefix + hexValue
	if c, err := CanonicalServiceID(id, false); err != nil || c != id {
		t.Fatalf("CanonicalServiceID(%q) = %q, %v", id, c, err)
	}
	for _, s := range []string{
		ContactPrefix + strings.ToUpper(hexValue),
		"CONTACT:" + hexValue,
		ContactPrefix + hexValue[1:],
		ContactPrefix + hexValue + "0",
		ContactPrefix + hexValue[:63] + "g",
		ContactPrefix,
		ContactPrefix + hexValue + "/",
		ContactPrefix + hexValue + ".example.com",
		"contact:https://example.com",
		"https://contact:" + hexValue,
		"app:contact:" + hexValue,
	} {
		if _, err := CanonicalServiceID(s, true); err == nil {
			t.Errorf("CanonicalServiceID(%q) accepted", s)
		}
	}
	master := sha256.Sum256([]byte("vaultysid/test/master"))
	a, err := Derive(master[:], id, Options{})
	if err != nil {
		t.Fatal(err)
	}
	b, err := Derive(master[:], "app:contact.example", Options{})
	if err != nil {
		t.Fatal(err)
	}
	if a.DID() == b.DID() {
		t.Error("contact and app identities coincide")
	}
}
